package com.omkarsadhana.portfolio.gallery; import java.nio.file.*; import java.util.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/gallery") @CrossOrigin public class GalleryController { @GetMapping public Map<String,List<String>> all(){return Map.of("photos",scan("photos"),"videos",scan("videos"),"graphic-designs",scan("graphic-designs"));} private List<String> scan(String folder){Path p=Path.of("assets/gallery",folder); if(!Files.exists(p)) return List.of(); try(var s=Files.list(p)){return s.filter(Files::isRegularFile).map(x->"/assets/gallery/"+folder+"/"+x.getFileName()).toList();}catch(Exception e){return List.of();}} }